# ORFs both strands min 100 aa? find all ORFs with ATG and stop in frame
def orfs(s, min_aa=50):
    res=[]
    for strand,ss in [(1,s),( -1, revcomp(s))]:
        for frame in range(3):
            i=frame
            while i < len(ss)-2:
                if ss[i:i+3]=='ATG':
                    j=i
                    while j < len(ss)-2:
                        cod=ss[j:j+3]
                        if cod in ('TAA','TAG','TGA'):
                            break
                        j+=3
                    if j < len(ss)-2:
                        aa=(j-i)//3
                        if aa>=min_aa:
                            if strand==1:
                                res.append((i+1,j+3,aa,strand,ss[i:j+3]))
                            else:
                                # convert coords to plus strand: revcomp position
                                start=n-(j+3)+1
                                end=n-i
                                res.append((start,end,aa,strand,ss[i:j+3]))
                    i=j+3
                else:
                    i+=3
    return res

def revcomp(s):
    return s.translate(str.maketrans('ACGT','TGCA'))[::-1]

