# microsatellites period 1-6 exact runs >=? 
def find_ssr(s, min_copies=3):
    out=[]
    for p in range(1,7):
        for i in range(len(s)-p*min_copies+1):
            unit=s[i:i+p]
            # skip if not canonical? find run
            k=0
            while i+(k+1)*p<=len(s) and s[i+k*p:i+(k+1)*p]==unit:
                k+=1
            if k>=min_copies:
                out.append((i+1, i+k*p, p, k, unit))
    # collapse: keep maximal at each position/period
    return out
