import re
seq=''.join(x.strip() for x in open('region.fasta') if not x.startswith('>'))
n=len(seq)
def gc_oe(w):
    L=len(w); gc=sum(w.count(x) for x in 'GC')/L
    c=w.count('C'); g=w.count('G'); cg=len(re.findall('CG',w))
    oe=cg/(c*g/L) if c*g else 0
    return gc,oe
for W in [100,150,200,300]:
    flag=[]
    for i in range(0,n-W+1):
        gc,oe=gc_oe(seq[i:i+W])
        flag.append(gc>0.5 and oe>0.6)
    islands=[]
    i=0
    while i<len(flag):
        if flag[i]:
            j=i
            while j+1<len(flag) and flag[j+1]: j+=1
            s=i+1; e=j+W
            if e-s+1>=200:
                islands.append((s,e))
            i=j+1
        else: i+=1
    merged=[]
    for s,e in islands:
        if merged and s<=merged[-1][1]+1:
            merged[-1]=(merged[-1][0],max(merged[-1][1],e))
        else: merged.append((s,e))
    print('W',W, 'islands:')
    for s,e in merged:
        gc,oe=gc_oe(seq[s-1:e])
        print(' ',s,e,len(seq[s-1:e]),round(gc,3),round(oe,3))

